async function backfillJobsToCalendar(jobs) {
  let synced = 0;
  let failed = 0;
  for (const job of jobs) {
    if (job.calEventId) {
      synced++;
      continue;
    }
    const id = await createJobEvent(job);
    if (id) synced++;
    else failed++;
    await new Promise((r) => setTimeout(r, 200));
  }
  return { synced, failed };
}

