async function handleResendWebhook(event) {
  const { type, data } = event;
  const emailId = data.email_id;
  const sendId = data.tags?.send_id ? Number(data.tags.send_id) : null;
  console.log(`[resend/webhook] ${type} \u2014 emailId=${emailId} sendId=${sendId}`);
  const now = new Date(data.created_at);
  if (sendId) {
    const update = {};
    if (type === "email.opened") {
      update.openedAt = now;
      update.status = "opened";
    }
    if (type === "email.clicked") {
      update.clickedAt = now;
      update.status = "clicked";
    }
    if (type === "email.bounced") {
      update.status = "bounced";
    }
    if (type === "email.complained") {
      update.status = "unsubscribed";
    }
    if (Object.keys(update).length) {
      await db.update(campaignSendsTable).set(update).where(eq(campaignSendsTable.id, sendId)).catch(console.error);
    }
  }
  if (emailId) {
    const update = {};
    if (type === "email.opened") {
      update.openedAt = now;
      update.status = "opened";
    }
    if (type === "email.clicked") {
      update.clickedAt = now;
      update.status = "clicked";
    }
    if (type === "email.bounced") {
      update.status = "bounced";
    }
    if (Object.keys(update).length) {
      await db.update(leadActivityTable).set(update).where(eq(leadActivityTable.externalId, emailId)).catch(console.error);
    }
  }
}

