var PRICE_QUESTION_PATTERNS = [
  /^\s*(what(?:'s| is| s)? )?(?:the )?(?:price|cost|rate|quote)( for| of)?\s+[a-z0-9 ',-]+\??\s*$/i,
  /^\s*how much( is| for| does| would| will)?\s+[a-z0-9 ',-]+\??\s*$/i,
  /^\s*do you (?:do|offer)\s+[a-z0-9 ',-]+\??\s*$/i
];
var HANDOFF_KEYWORDS = [
  "address",
  "moved",
  "different house",
  "new home",
  "new house",
  "complaint",
  "complain",
  "refund",
  "reschedule",
  "cancel my",
  "lawyer",
  "attorney",
  "manager",
  "owner",
  "wrong",
  "mistake",
  "didn'?t pay",
  "still owe",
  "?:"
  // multi-question marker (semicolons / colons in middle of sentence)
];
var ADDON_KEYWORDS = [
  "driveway",
  "concrete",
  "deck",
  "patio",
  "fence",
  "windows",
  "screens",
  "roof",
  "gutter",
  "bundle",
  "add-on",
  "addon",
  "and the"
];
function classifyReply(body) {
  const text2 = (body ?? "").trim();
  if (!text2) return { classification: "unclassified", reason: "empty" };
  if (isSmsStopMessage(text2)) {
    return { classification: "opt_out", reason: `stop_keyword:${text2.toLowerCase()}` };
  }
  const lower = text2.toLowerCase();
  const wordCount = text2.split(/\s+/).length;
  const questionCount = (text2.match(/\?/g) ?? []).length;
  if (questionCount >= 2) {
    return { classification: "human_handoff", reason: "multi_question" };
  }
  if (wordCount > 30) {
    return { classification: "human_handoff", reason: "long_reply" };
  }
  for (const kw of ADDON_KEYWORDS) {
    if (lower.includes(kw)) {
      return { classification: "human_handoff", reason: `mentions_addon:${kw}` };
    }
  }
  for (const kw of HANDOFF_KEYWORDS) {
    if (kw === "?:") continue;
    if (new RegExp(`\\b${kw}\\b`, "i").test(text2)) {
      return { classification: "human_handoff", reason: `keyword:${kw}` };
    }
  }
  for (const pat of PRICE_QUESTION_PATTERNS) {
    if (pat.test(text2)) {
      return { classification: "simple_question", reason: "price_pattern" };
    }
  }
  if (/^\s*(yes|yep|yeah|yup|sure|ok|okay|sounds good|let'?s do it|i'?m in|book me)[.! ]*$/i.test(text2)) {
    return { classification: "human_handoff", reason: "positive_confirmation" };
  }
  return { classification: "human_handoff", reason: "default" };
}

