(async () => {
  try {
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS hh_conversations (
        id TEXT PRIMARY KEY,
        lead_id TEXT REFERENCES leads(id),
        phone TEXT NOT NULL,
        customer_name TEXT,
        status TEXT NOT NULL DEFAULT 'active',
        mode TEXT NOT NULL DEFAULT 'human',
        discord_thread_id TEXT,
        last_message_at TIMESTAMPTZ,
        last_message_body TEXT,
        last_message_role TEXT,
        unread_count INTEGER DEFAULT 0,
        campaign_id INTEGER,
        campaign_send_id INTEGER,
        metadata JSONB,
        created_at TIMESTAMPTZ DEFAULT NOW(),
        updated_at TIMESTAMPTZ DEFAULT NOW()
      )
    `).catch(
      (e) => console.warn("[startup] hh_conversations table:", e.message)
    );
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS hh_conversation_messages (
        id TEXT PRIMARY KEY,
        conversation_id TEXT REFERENCES hh_conversations(id),
        role TEXT NOT NULL,
        body TEXT NOT NULL,
        channel TEXT,
        twilio_sid TEXT,
        discord_message_id TEXT,
        created_at TIMESTAMPTZ DEFAULT NOW()
      )
    `).catch(
      (e) => console.warn("[startup] hh_conversation_messages table:", e.message)
    );
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS hh_rep_earnings (
        id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
        rep_id TEXT,
        rep_email TEXT NOT NULL,
        job_id TEXT,
        lead_id TEXT,
        customer_name TEXT,
        earn_type TEXT NOT NULL,
        gross_amount_cents INTEGER NOT NULL DEFAULT 0,
        commission_cents INTEGER NOT NULL,
        commission_label TEXT,
        status TEXT NOT NULL DEFAULT 'pending',
        serviced_at TIMESTAMPTZ,
        payout_eligible_at TIMESTAMPTZ,
        review_triggered BOOLEAN DEFAULT FALSE,
        created_at TIMESTAMPTZ DEFAULT NOW()
      )
    `).catch(
      (e) => console.warn("[startup] hh_rep_earnings table:", e.message)
    );
    await db.execute(sql`
      CREATE TABLE IF NOT EXISTS hh_tech_earnings (
        id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
        tech_id INTEGER NOT NULL,
        tech_name TEXT,
        tech_email TEXT,
        job_id TEXT NOT NULL,
        customer_name TEXT,
        service_type TEXT,
        gross_amount_cents INTEGER NOT NULL DEFAULT 0,
        commission_cents INTEGER NOT NULL,
        commission_rate TEXT,
        status TEXT NOT NULL DEFAULT 'pending',
        completed_at TIMESTAMPTZ,
        payout_eligible_at TIMESTAMPTZ,
        created_at TIMESTAMPTZ DEFAULT NOW()
      )
    `).catch(
      (e) => console.warn("[startup] hh_tech_earnings table:", e.message)
    );
    await db.execute(sql`
      INSERT INTO hh_settings (key, value)
      VALUES ('tech_commission_config', ${JSON.stringify({
      nassim: { rate: 0.25 },
      harrison: { rate: 0.2 },
      cameron: { rate: 0.2 }
    })})
      ON CONFLICT (key) DO NOTHING
    `).catch(
      (e) => console.warn("[startup] tech_commission_config seed:", e.message)
    );
    console.log("[startup] Conversations & earnings tables ready");
  } catch (err) {
    console.error("[startup] migration error:", err);
  }
})();
